<section class="container page-section" id="permainan">
	<p><a class="btn btn-outline-secondary" href="<?php echo study_arena_game_url('quest'); ?>"><i class="bi bi-arrow-left me-2" aria-hidden="true"></i>Peta episode</a> · <a href="<?php echo site_url('belajar/arena/riwayat'); ?>">Riwayat</a></p><div class="feature-card"><p class="eyebrow">English Quest · tanpa timer</p><h1 class="h3"><?php echo html_escape($run['title_snapshot']); ?></h1>
	<?php if ($error): ?><div class="alert alert-danger" role="alert"><?php echo html_escape($error); ?> <a href="<?php echo site_url('belajar/arena/main/'.$run['id']); ?>">Muat ulang</a></div><?php endif; ?>
	<?php if ($run['status'] === 'running'): $step = $run['step']; ?><p>Adegan <?php echo (int) $run['position'] + 1; ?>/<?php echo (int) $run['steps_count']; ?> · <?php echo html_escape($step['place']); ?></p>
	<div class="border rounded p-3 p-md-4 mb-3"><p class="eyebrow"><?php echo html_escape($step['speaker']); ?></p><p class="h5 lh-base" lang="en" data-english-speech><?php echo html_escape($step['english']); ?></p><details<?php echo $run['translation'] === '1' ? ' open' : ''; ?>><summary>Arti dialog</summary><p class="mt-2"><?php echo html_escape($step['translation']); ?></p></details></div>
		<?php if ($run['audio'] === '1'): ?><button class="btn btn-outline-secondary mb-2" type="button" data-english-listen hidden>Dengarkan contoh</button><p class="small text-secondary" data-english-audio-status>Audio opsional memakai suara Inggris lokal perangkat jika tersedia. Transkrip tetap tersedia tanpa audio; tidak merekam mikrofon.</p><?php endif; ?>
	<h2 class="h5"><?php echo html_escape($step['prompt']); ?></h2><?php if ($step['kind'] === 'story'): ?><p class="small">Pilih tindakan tokoh. Tidak ada nilai benar/salah atau bonus berbeda untuk pilihan cerita ini.</p><?php endif; ?>
		<?php if ($run['feedback']): $feedback = $run['feedback']; ?><div class="alert alert-info" role="status"><strong><?php echo $feedback['correct'] === NULL ? 'Pilihan cerita tersimpan.' : ($feedback['correct'] ? 'Jawaban sesuai.' : 'Mari pelajari lagi.'); ?></strong><p><?php echo html_escape($feedback['message']); ?></p><?php if ($feedback['solution']): ?><p>Contoh jawaban: <strong><?php echo html_escape($feedback['solution']); ?></strong></p><?php endif; ?><p class="mb-0">Kosakata: <strong><?php echo html_escape($feedback['word']); ?></strong> — <?php echo html_escape($feedback['meaning']); ?></p></div><?php endif; ?>
		<?php echo form_open('belajar/arena/main/'.$run['id']); ?><input type="hidden" name="revision" value="<?php echo (int) $run['revision']; ?>">
		<?php if ($run['feedback']): ?><button class="btn btn-primary" name="action" value="next">Sudah ditinjau, lanjutkan cerita</button>
	<?php else: ?><input type="hidden" name="action" value="answer"><?php if ($step['kind'] === 'sentence'): ?><p class="border rounded p-3 text-break" lang="en"><?php echo html_escape($step['words']); ?></p><label class="form-label" for="quest-sentence">Susun kata-kata di atas</label><input class="form-control mb-3" id="quest-sentence" name="value" maxlength="200" required autocomplete="off" spellcheck="false"><p class="small text-secondary">Gunakan kata yang disediakan, bukan data pribadi. Huruf besar dan tanda baca tidak memengaruhi hasil.</p>
	<?php else: ?><fieldset><legend class="h6">Pilihanmu</legend><?php foreach ($step['choices'] as $key => $label): ?><div class="form-check border rounded p-3 ps-5 mb-2"><input class="form-check-input" id="quest-<?php echo $key; ?>" type="radio" name="value" value="<?php echo $key; ?>" required><label class="form-check-label text-break" for="quest-<?php echo $key; ?>"><?php echo html_escape($label); ?></label></div><?php endforeach; ?></fieldset><?php endif; ?><button class="btn btn-primary mt-2" type="submit">Simpan pilihan</button><?php endif; ?><?php echo form_close(); ?>
	<details class="mt-4"><summary>Akhiri episode lebih awal</summary><p>Untuk jeda, cukup kembali ke peta. Jika diakhiri sekarang, riwayat disimpan tetapi episode belum selesai.</p><?php echo form_open('belajar/arena/main/'.$run['id']); ?><input type="hidden" name="revision" value="<?php echo (int) $run['revision']; ?>"><button class="btn btn-outline-danger" name="action" value="stop">Ya, akhiri</button><?php echo form_close(); ?></details>
	<?php else: ?><h2 class="h4"><?php echo $run['status'] === 'completed' ? 'Episode sudah dijelajahi!' : 'Episode diakhiri lebih awal'; ?></h2><p><?php echo (int) $run['position']; ?>/<?php echo (int) $run['steps_count']; ?> adegan ditinjau. Tantangan bahasa: <?php echo (int) $run['correct_count']; ?>/<?php echo (int) $run['question_count']; ?> sesuai; pilihan cerita tidak masuk pembagi. Ini hasil latihan, bukan nilai ujian.</p>
	<h3 class="h5">Jurnal petualangan</h3><ol class="ps-3"><?php foreach ($run['review'] as $item): ?><li class="mb-3"><strong><?php echo html_escape($item['place']); ?></strong><p class="mb-1"><?php echo html_escape($item['prompt']); ?></p><p class="mb-1"><?php echo html_escape($item['selected'] ?: $item['solution']); ?></p><?php if ($item['solution'] && $item['solution'] !== $item['selected']): ?><p class="small mb-1">Contoh jawaban: <strong><?php echo html_escape($item['solution']); ?></strong></p><?php endif; ?><p class="small mb-1"><?php echo html_escape($item['message']); ?></p><p class="small text-secondary"><?php echo html_escape($item['word'].' — '.$item['meaning']); ?></p></li><?php endforeach; ?></ol>
	<p class="small text-secondary">Versi konten <?php echo (int) $run['content_version']; ?> · selesai <?php echo html_escape(study_format_datetime($run['finished_at'])); ?>. Jurnal lama tidak ditimpa oleh pengulangan.</p><a class="btn btn-primary" href="<?php echo study_arena_game_url('quest'); ?>">Kembali ke peta episode</a><?php endif; ?></div>
</section><script src="<?php echo base_url('assets/js/english-audio.js'); ?>" defer></script>
